cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case ---
  it.todo("quote with an empty item list -- premium 5 G (processing fee only)");

  // --- Quote: main item base premiums (parallel catalogue: each type has own value/premium) ---
  it.todo("quote for a single plain sword -- premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("quote for a single plain amulet -- premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quote for a single plain staff -- premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quote for a single plain potion -- premium 49 G (40 base + 4 first insurance + 5 fee)");

  // --- Quote: component base premiums and the block of 3 ---
  it.todo("quote for 1 rune -- base premium 25 G");
  it.todo("quote for 2 runes -- base premium 50 G (no block)");
  it.todo("quote for 3 runes -- base premium 60 G (block applies)");
  it.todo("quote for 4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("quote for 7 runes -- base premium 175 G (no block; block requires exactly 3)");
  it.todo("quote for 1 moonstone -- base premium 25 G (moonstone priced like a rune)");
  it.todo("quote for 3 moonstones -- base premium 60 G (block applies to moonstones too)");

  // --- Quote: 'alike' means same type (clarifying question) ---
  it.todo("quote for 2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
  it.todo("quote for 3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("quote for a cursed sword -- curse adds 50 G (50 % of the item's base premium)");
  it.todo("quote for a sword with enchantment 5 -- high-enchantment surcharge 30 G applies (threshold is >= 5)");
  it.todo("quote for a sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo("quote for a cursed sword with enchantment 5 -- both surcharges apply (50 G + 30 G)");

  // --- Quote: policy-wide modifiers ---
  it.todo("quote for a customer with exactly 2 years with MHPCO -- 20 % loyalty discount applies");
  it.todo("quote for a customer with 1 year with MHPCO -- no loyalty discount");
  it.todo("quote always adds the 10 % first-insurance surcharge per item, regardless of customer history");
  it.todo("second quote in a scenario -- 15 % follow-up-contract discount on the policy base premium");
  it.todo("third quote in a scenario -- 15 % follow-up-contract discount also applies");

  // --- Quote: modifier scope on multi-item policies (clarifying question) ---
  it.todo("quote for a cursed sword + plain amulet -- policy base 160 G, curse adds 50 G (only the cursed item's base) -> 210 G before further modifiers and fee");

  // --- Quote: rounding in MHPCO's favour ---
  it.todo("quote whose raw premium is 197.5 G -- final premium 198 G (rounded up)");
  it.todo("quote keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Quote: error cases ---
  it.todo("quote with an unknown item type (broomstick) -- CLI exits non-zero, error on stderr, no results on stdout");

  // --- Claim: insurance sum and cap ---
  it.todo("policy covering a sword and an amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes -- insurance sum 1750 G (block discount affects premium only), cap 3500 G");
  it.todo("cursed sword with premium 165 G -- cap 2000 G (based on unmodified insurance value)");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("claim on a steel sword enchantment 3, damage 500 G -- payout 400 G (full minus 100 G deductible)");
  it.todo("claim on a rune (no enchantment, no material), damage 200 G -- payout 100 G (full minus deductible)");
  it.todo("claim with damage below the deductible -- payout 0 G, never negative");

  // --- Claim: special clauses ---
  it.todo("claim on a steel sword enchantment 9, damage 1000 G -- payout 400 G (50 % first, then deductible)");
  it.todo("claim on a steel sword enchantment 8, damage 1000 G -- payout 400 G (threshold is >= 8)");
  it.todo("claim on a steel sword enchantment 7, damage 1000 G -- payout 900 G (no high-enchantment clause)");
  it.todo("claim on a dragon-material sword enchantment 5, damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo("claim on a dragon-material sword enchantment 9, damage 1000 G -- payout 400 G (50 % rule wins over dragon material)");
  it.todo("claim on a dragon-material sword enchantment 8, damage 1000 G -- payout 400 G (high-enchantment clause applies, then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damaging a sword (500 G) and an amulet (300 G) -- payout 600 G (deductible once per damaged item)");
  it.todo("policy covering two swords, damages listing two sword entries -- each entry gets its own deductible");

  // --- Claim: cap exhaustion across claims ---
  it.todo("sword policy (cap 2000 G), first claim of 1500 G -- payout 1400 G, remainingCap 600 G");
  it.todo("sword policy (cap 2000 G), second claim of 1500 G -- payout 600 G, remainingCap 0 G (reduced to remaining cap)");

  // --- Claim: rounding in MHPCO's favour ---
  it.todo("claim whose raw payout is 350.5 G -- final payout 350 G (rounded down)");

  // --- Claim: error cases ---
  it.todo("claim naming an item not in the policy (amulet when only a sword is insured) -- CLI exits non-zero with error on stderr");
  it.todo("claim naming an unknown item type -- CLI exits non-zero with error on stderr");
  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- CLI exits non-zero, whole claim rejected");
  it.todo("claim with a damage entry of amount -200 -- CLI exits non-zero with error on stderr");

  // --- CLI ---
  it.todo("CLI reads the schema example from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
  it.todo("CLI processes steps sequentially so a claim refers to the policy of its quote step by zero-based index");
});
EOF
