 85	function insuranceValueOf(item: Item): number {
 86	  requireInsurableType(item.type);
 87	  if (isComponent(item)) {
 88	    return COMPONENT_INSURANCE_VALUE;
 89	  }
 90	  return MAIN_ITEM_INSURANCE_VALUES[item.type];
 91	}
