 93	function isComponent(item: Item): boolean {
 94	  return COMPONENT_TYPES.includes(item.type);
 95	}
 96	
 97	function isInsurableType(type: string): boolean {
 98	  return COMPONENT_TYPES.includes(type) || type in MAIN_ITEM_BASE_PREMIUMS;
 99	}
100	
101	/** A block of exactly 3 alike components is offered at a special base premium. */
102	function componentGroupBasePremium(items: Item[]): number {
103	  if (items.length === BLOCK_SIZE) {
104	    return BLOCK_BASE_PREMIUM;
105	  }
106	  return items.reduce((sum, item) => sum + basePremiumOf(item), 0);
107	}
108	
109	/** "Alike" components are components of exactly the same type. */
110	function groupAlikeComponents(items: Item[]): Item[][] {
111	  const groups = new Map<string, Item[]>();
112	  for (const item of items.filter(isComponent)) {
113	    const group = groups.get(item.type) ?? [];
114	    group.push(item);
115	    groups.set(item.type, group);
116	  }
117	  return [...groups.values()];
118	}
