120	function policyBasePremium(items: Item[]): number {
121	  const mainItems = items.filter((item) => !isComponent(item));
122	  const mainBase = mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0);
123	  const componentBase = groupAlikeComponents(items).reduce(
124	    (sum, group) => sum + componentGroupBasePremium(group),
125	    0,
