170	function policyModifierRate(customer: Customer, previousContracts: number): number {
171	  return (
172	    FIRST_INSURANCE_SURCHARGE_RATE -
173	    (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
174	    (isFollowUpContract(previousContracts) ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0)
175	  );
176	}
