185	interface Policy {
186	  items: Item[];
187	  remainingCap: number;
188	}
189	
190	function isSeverelyEnchanted(item: Item): boolean {
191	  return (item.enchantment ?? 0) >= SEVERE_ENCHANTMENT_LEVEL;
192	}
