223	 * one sword cannot answer two sword damages. The whole claim is rejected when
224	 * any damage has no item left to settle against.
225	 */
226	function allocateDamagesToInsuredItems(policy: Policy, damages: Damage[]): Item[] {
227	  const available = [...policy.items];
228	  return damages.map((damage) => {
229	    const index = available.findIndex((item) => item.type === damage.itemType);
230	    if (index === -1) {
