244	function settleClaim(policy: Policy, step: ClaimStep): StepResult {
245	  const damages = step.incident.damages;
246	  damages.forEach(requireReportableDamage);
247	  const insuredItems = allocateDamagesToInsuredItems(policy, damages);
248	  const desired = damages.reduce(
249	    (sum, entry, index) => sum + payoutForDamage(insuredItems[index], entry.amount),
250	    0,
251	  );
252	  const payout = roundPayoutInMhpcoFavour(Math.min(desired, policy.remainingCap));
253	  policy.remainingCap -= payout;
254	  return { payout, remainingCap: policy.remainingCap };
255	}
256	
257	export function runScenario(scenario: Scenario): StepResult[] {
258	  const results: StepResult[] = [];
259	  const policies = new Map<number, Policy>();
260	  let contracts = 0;
261	  scenario.steps.forEach((step, index) => {
262	    if (step.op === "quote") {
263	      results.push({ premium: quotePremium(step.items, scenario.customer, contracts) });
264	      policies.set(index, openPolicy(step.items));
265	      contracts += 1;
266	    } else {
267	      results.push(settleClaim(policies.get(step.policy) as Policy, step));
268	    }
269	  });
270	  return results;
271	}

